<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyApiApprovalFixture.php';
use DigiForge\Core\Settings;
use DigiForge\Database\Tables;
use DigiForge\Listings\{EtsyWebhookDeduplicator,EtsyWebhookIntake};
use DigiForge\Orders\PaidIntakeEvidence;

/** Actual signed local intake ledgers; no claim that the payload/order binding was persisted. */
final class PaidIntakeEvidenceTest extends WP_UnitTestCase {
 private PrintifyApiApprovalFixture $fixture;
 private array $snapshots=[];
 private int $http=0;
 private $deny;
 public function setUp():void {parent::setUp();\DigiForge\Core\Activator::activate();global $wpdb;foreach([Tables::orders(),Tables::order_line_items(),Tables::webhook_evidence(),Tables::idempotency()]as $table)$this->snapshots[$table]=$wpdb->get_results('SELECT * FROM '.$table,ARRAY_A);$this->fixture=new PrintifyApiApprovalFixture();$this->fixture->boot();Settings::protectProduction();$this->deny=function(){$this->http++;return new WP_Error('unexpected_http');};add_filter('pre_http_request',$this->deny);}
 public function tearDown():void {remove_filter('pre_http_request',$this->deny);try{global $wpdb;$wpdb->query('ROLLBACK');foreach($this->snapshots as $table=>$rows){$wpdb->query('DELETE FROM '.$table);foreach($rows as $row)$wpdb->insert($table,$row,array_fill(0,count($row),'%s'));}$this->fixture->restore();self::assertSame(0,$this->http);}finally{parent::tearDown();}}
 public function testActualCompleteLedgersReturnOnlyWhitelistedInternalCorrelationWithoutWrites():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class),'A scoped read-only paid-intake evidence service is required.');[$order,$event,$body]=$this->intake();global $wpdb;$settings=$wpdb->get_results('SELECT * FROM '.Tables::settings().' ORDER BY setting_key',ARRAY_A);$queries=[];$observe=static function(string $sql)use(&$queries):string{$queries[]=$sql;return $sql;};add_filter('query',$observe);try{$view=(new PaidIntakeEvidence())->inspect('personalized_pod',$order);}finally{remove_filter('query',$observe);}self::assertNotWPError($view);self::assertSame('COMPLETE',$view['intake_state']);self::assertSame('STORED_ORDER_KEY',$view['correlation_basis']);self::assertSame('NOT_RECORDED',$view['payload_order_binding']);self::assertSame($event,$view['event_id']);self::assertSame(hash('sha256',$body),$view['body_sha256']);self::assertSame('PROCESSED',$view['receipt_status']);self::assertSame('PROCESSED',$view['dedup_status']);self::assertMatchesRegularExpression('/^[a-f0-9]{64}$/D',$view['result_hash']);self::assertSame(get_current_user_id(),$view['actor_id']);self::assertSame($order,$view['order']['id']);self::assertSame(['channel','currency','environment','external_order_reference','id','shop_reference','state'],array_values(array_unique($this->sortedKeys($view['order']))));self::assertTrue($view['read_only']);self::assertFalse($view['retry_permitted']);self::assertFalse($view['production_ready']);self::assertFalse($view['external_execution_authorized']);self::assertFalse($view['external_execution_performed']);self::assertStringNotContainsString('PRIVATE-BUYER',json_encode($view));self::assertStringNotContainsString('PRIVATE-HEADER',json_encode($view));self::assertArrayNotHasKey('headers_evidence',$view);self::assertArrayNotHasKey('idempotency_key',$view['order']);self::assertSame($view['snapshot_hash'],(new PaidIntakeEvidence())->inspect('personalized_pod',$order)['snapshot_hash']);foreach($queries as $sql)self::assertDoesNotMatchRegularExpression('/^\s*(INSERT|UPDATE|DELETE|REPLACE|CREATE|ALTER|DROP)\b/i',$sql);self::assertSame($settings,$wpdb->get_results('SELECT * FROM '.Tables::settings().' ORDER BY setting_key',ARRAY_A));self::assertTrue(Settings::safety_locked());
 }
 public function testRealFailedTransitionLeavesReceivedOrderAndBothFailedLedgers():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order]=$this->intake('transition');$view=(new PaidIntakeEvidence())->inspect('personalized_pod',$order);self::assertNotWPError($view);self::assertSame('FAILED',$view['intake_state']);self::assertSame('RECEIVED',$view['order']['state']);self::assertSame('FAILED',$view['receipt_status']);self::assertSame('FAILED',$view['dedup_status']);self::assertNull($view['result_hash']);
 }
 public function testRealPartialCompletionAndMissingDedupRemainUncertain():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order,$event]=$this->intake('completion');$service=new PaidIntakeEvidence();$view=$service->inspect('personalized_pod',$order);self::assertNotWPError($view);self::assertSame('UNCERTAIN',$view['intake_state']);self::assertSame('VERIFIED',$view['receipt_status']);self::assertSame('PROCESSED',$view['dedup_status']);self::assertNull($view['result_hash']);global $wpdb;$wpdb->delete(Tables::idempotency(),['operation_key'=>'etsy_webhook:'.hash('sha256',$event)]);$view=$service->inspect('personalized_pod',$order);self::assertNotWPError($view);self::assertSame('UNCERTAIN',$view['intake_state']);self::assertNull($view['dedup_status']);self::assertNull($view['result_hash']);
 }
 public function testMissingCompletionHashesAndReceivedOrderAreNeverCompleteButHoldDoesNotEraseIntakeCompletion():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order,$event]=$this->intake();$service=new PaidIntakeEvidence();global $wpdb;$receipt=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::webhook_evidence().' WHERE event_id=%s',$event),ARRAY_A);$dedup=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::idempotency().' WHERE operation_key=%s','etsy_webhook:'.hash('sha256',$event)),ARRAY_A);$wpdb->update(Tables::webhook_evidence(),['result_hash'=>''],['id'=>$receipt['id']]);$wpdb->update(Tables::idempotency(),['response_hash'=>''],['id'=>$dedup['id']]);$view=$service->inspect('personalized_pod',$order);self::assertNotWPError($view);self::assertSame('UNCERTAIN',$view['intake_state']);self::assertNull($view['result_hash']);$wpdb->update(Tables::webhook_evidence(),['result_hash'=>$receipt['result_hash']],['id'=>$receipt['id']]);$wpdb->update(Tables::idempotency(),['response_hash'=>$dedup['response_hash']],['id'=>$dedup['id']]);$wpdb->update(Tables::orders(),['state'=>'RECEIVED'],['id'=>$order]);$view=$service->inspect('personalized_pod',$order);self::assertNotWPError($view);self::assertSame('UNCERTAIN',$view['intake_state']);$wpdb->update(Tables::orders(),['state'=>'REVIEW_REQUIRED'],['id'=>$order]);PrintifyApiApprovalFixture::checked((new \DigiForge\Orders\Repository())->transition('order',$order,'ON_HOLD'));$view=$service->inspect('personalized_pod',$order);self::assertNotWPError($view);self::assertSame('COMPLETE',$view['intake_state']);self::assertSame('ON_HOLD',$view['order']['state']);self::assertFalse($view['production_ready']);
 }
 public function testMalformedIdentityForeignScopeStatusAndConflictingHashesFailClosed():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order,$event]=$this->intake();global $wpdb;$receipt=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.Tables::webhook_evidence().' WHERE event_id=%s',$event));$dedup=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.Tables::idempotency().' WHERE operation_key=%s','etsy_webhook:'.hash('sha256',$event)));$service=new PaidIntakeEvidence();
  foreach([[Tables::orders(),$order,'channel','manual'],[Tables::orders(),$order,'environment','test'],[Tables::orders(),$order,'shop_reference','digital'],[Tables::orders(),$order,'idempotency_key','arbitrary-key'],[Tables::webhook_evidence(),$receipt,'event_type','order.shipped'],[Tables::webhook_evidence(),$receipt,'verification_status','UNVERIFIED'],[Tables::webhook_evidence(),$receipt,'shop_reference','digital'],[Tables::webhook_evidence(),$receipt,'body_sha256','malformed'],[Tables::webhook_evidence(),$receipt,'processing_status','UNKNOWN'],[Tables::idempotency(),$dedup,'operation_type','OTHER'],[Tables::idempotency(),$dedup,'response_hash',str_repeat('a',64)],[Tables::idempotency(),$dedup,'status','MALFORMED']]as [$table,$id,$field,$bad]){$old=$wpdb->get_var($wpdb->prepare('SELECT '.$field.' FROM '.$table.' WHERE id=%d',$id));$wpdb->update($table,[$field=>$bad],['id'=>$id]);try{self::assertWPError($service->inspect('personalized_pod',$order),$field);}finally{$wpdb->update($table,[$field=>$old],['id'=>$id]);}}
  $stored=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::webhook_evidence().' WHERE id=%d',$receipt),ARRAY_A);$wpdb->delete(Tables::webhook_evidence(),['id'=>$receipt]);self::assertWPError($service->inspect('personalized_pod',$order));$wpdb->insert(Tables::webhook_evidence(),$stored,array_fill(0,count($stored),'%s'));$wpdb->update(Tables::webhook_evidence(),['processing_status'=>'FAILED'],['id'=>$receipt]);$wpdb->update(Tables::idempotency(),['status'=>'FAILED','response_hash'=>str_repeat('b',64)],['id'=>$dedup]);self::assertWPError($service->inspect('personalized_pod',$order));
 }
 public function testUnauthorizedActorsAreDeniedBeforeAnyPrivateOrderOrLedgerRead():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order]=$this->intake();$private=[];$observe=static function(string $sql)use(&$private):string{foreach([Tables::orders(),Tables::webhook_evidence(),Tables::idempotency()]as $table)if(str_contains($sql,'FROM '.$table))$private[]=$sql;return $sql;};add_filter('query',$observe);try{$service=new PaidIntakeEvidence();self::assertWPError($service->inspect('digital',$order));wp_set_current_user(0);self::assertWPError($service->inspect('personalized_pod',$order));$this->fixture->owner();$actor=wp_get_current_user();$actor->add_cap('manage_digiforge',false);try{self::assertWPError($service->inspect('personalized_pod',$order));}finally{$actor->add_cap('manage_digiforge');}}finally{remove_filter('query',$observe);}self::assertSame([],$private);
 }
 public function testQueryFailureAndChangedSecondReadCannotReturnPrivateEvidence():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order,$event]=$this->intake();global $wpdb;$service=new PaidIntakeEvidence();$fault=static fn(string $sql):string=>str_starts_with($sql,'SELECT * FROM '.Tables::webhook_evidence())?'SELECT * FROM missing_paid_intake_receipt':$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$fault);try{self::assertWPError($service->inspect('personalized_pod',$order));}finally{remove_filter('query',$fault);$wpdb->suppress_errors($prior);}$reads=0;$changed=false;$race=static function(string $sql)use($wpdb,$order,&$reads,&$changed):string{if(str_starts_with($sql,'SELECT o.* FROM '.Tables::orders())&&++$reads===2){$wpdb->update(Tables::orders(),['external_order_reference'=>'changed-during-inspection'],['id'=>$order]);$changed=true;}return $sql;};add_filter('query',$race);try{self::assertWPError($service->inspect('personalized_pod',$order));}finally{remove_filter('query',$race);}self::assertTrue($changed);
 }
 public function testLastLedgerReadActorOrModuleRevocationDeniesOutput():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));foreach(['logout','module']as $mode){$this->fixture->owner();[$order]=$this->intake();$actor=wp_get_current_user();$reads=0;$changed=false;$race=static function(string $sql)use($actor,$mode,&$reads,&$changed):string{if(str_starts_with($sql,'SELECT * FROM '.Tables::idempotency())&&++$reads===2){$changed=true;if($mode==='logout')wp_set_current_user(0);else $actor->add_cap('manage_digiforge_pod',false);}return $sql;};add_filter('query',$race);try{self::assertWPError((new PaidIntakeEvidence())->inspect('personalized_pod',$order));}finally{remove_filter('query',$race);$actor->add_cap('manage_digiforge_pod');$this->fixture->owner();}self::assertTrue($changed);}
 }
 public function testRealCommittedSecondConnectionChangeCannotBePresentedAsCurrentInsideOldSnapshot():void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order]=$this->intake();global $wpdb;self::assertNotFalse($wpdb->query('COMMIT'));self::assertNotFalse($wpdb->query('SET autocommit=1'));$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->set_prefix($wpdb->prefix);$other->suppress_errors(true);$isolationModes=['READ-COMMITTED'=>'READ COMMITTED','REPEATABLE-READ'=>'REPEATABLE READ','READ-UNCOMMITTED'=>'READ UNCOMMITTED','SERIALIZABLE'=>'SERIALIZABLE'];$priorIsolation=strtoupper((string)$wpdb->get_var('SELECT @@session.tx_isolation'));self::assertArrayHasKey($priorIsolation,$isolationModes);$table=Tables::orders();$before=$other->get_var($other->prepare('SELECT external_order_reference FROM '.$table.' WHERE id=%d',$order));$changed='committed-on-other-connection-'.wp_generate_uuid4();
  try {self::assertNotFalse($wpdb->query('SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ'));self::assertNotFalse($wpdb->query('START TRANSACTION WITH CONSISTENT SNAPSHOT'));self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));self::assertSame('REPEATABLE-READ',strtoupper((string)$wpdb->get_var('SELECT @@session.tx_isolation')));self::assertSame($before,$wpdb->get_var($wpdb->prepare('SELECT external_order_reference FROM '.$table.' WHERE id=%d',$order)));$service=new PaidIntakeEvidence();$primed=$service->inspect('personalized_pod',$order);
   self::assertNotFalse($other->query('SET SESSION innodb_lock_wait_timeout=2'));self::assertNotFalse($other->query('START TRANSACTION'));self::assertSame(1,$other->update($table,['external_order_reference'=>$changed],['id'=>$order]));self::assertNotFalse($other->query('COMMIT'));self::assertSame('0',(string)$other->get_var('SELECT @@session.in_transaction'));self::assertSame($changed,$other->get_var($other->prepare('SELECT external_order_reference FROM '.$table.' WHERE id=%d',$order)));self::assertSame($before,$wpdb->get_var($wpdb->prepare('SELECT external_order_reference FROM '.$table.' WHERE id=%d',$order)),'The first connection must demonstrably retain the old real repeatable-read snapshot.');self::assertWPError($service->inspect('personalized_pod',$order),'An old caller transaction cannot supply current order or intake evidence.');
  }finally{$wpdb->query('ROLLBACK');$wpdb->query('SET autocommit=1');$wpdb->query('SET SESSION TRANSACTION ISOLATION LEVEL '.$isolationModes[$priorIsolation]);$other->query('ROLLBACK');$other->close();}self::assertSame($priorIsolation,strtoupper((string)$wpdb->get_var('SELECT @@session.tx_isolation')));
 }
 public static function finalBoundaryRevocations():array {return [['logout'],['capability']];}
 /** @dataProvider finalBoundaryRevocations */
 public function testFinalBoundaryQueryCannotReleasePrivateDtoAfterActorOrCapabilityLoss(string $mode):void {
  self::assertTrue(class_exists(PaidIntakeEvidence::class));[$order]=$this->intake();$actor=wp_get_current_user();$reads=0;$changed=false;$race=static function(string $sql)use($actor,$mode,&$reads,&$changed):string{if(str_starts_with($sql,'SELECT @@session.in_transaction AS active,@@session.autocommit AS autocommit')&&++$reads===2){$changed=true;if($mode==='logout')wp_set_current_user(0);else $actor->add_cap('manage_digiforge_pod',false);}return $sql;};add_filter('query',$race);try{self::assertWPError((new PaidIntakeEvidence())->inspect('personalized_pod',$order),'The final transaction-boundary query cannot bypass current actor and native-capability admission.');}finally{remove_filter('query',$race);$actor->add_cap('manage_digiforge_pod');$this->fixture->owner();}self::assertTrue($changed);
 }
 private function intake(?string $fault=null):array {$event='paid-evidence-'.wp_generate_uuid4();$payload=['event_type'=>'order.paid','order_id'=>'local-evidence-'.wp_generate_uuid4(),'shop_id'=>'personalized_pod','buyer_id'=>'PRIVATE-BUYER','line_items'=>[]];$body=(string)wp_json_encode($payload);$now=time();$secret='synthetic-paid-evidence';$headers=['webhook-id'=>$event,'webhook-timestamp'=>(string)$now,'webhook-signature'=>'v1,'.base64_encode(hash_hmac('sha256',$event.'.'.$now.'.'.$body,$secret,true)),'private-fixture-header'=>'PRIVATE-HEADER'];global $wpdb;$filter=static function(string $sql)use($fault):string{if(($fault==='transition'&&str_starts_with($sql,'UPDATE `'.Tables::orders().'`'))||($fault==='completion'&&str_starts_with($sql,'UPDATE `'.Tables::webhook_evidence().'`')&&str_contains($sql,'PROCESSED')))return 'UPDATE missing_paid_evidence_transition SET state=1';return $sql;};$prior=$wpdb->suppress_errors(true);if($fault!==null)add_filter('query',$filter);try{$result=(new EtsyWebhookIntake(new EtsyWebhookDeduplicator()))->accept($body,$headers,'whsec_'.base64_encode($secret),$now);}finally{if($fault!==null)remove_filter('query',$filter);$wpdb->suppress_errors($prior);}if($fault===null)self::assertNotWPError($result);else self::assertWPError($result);$order=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.Tables::orders().' WHERE idempotency_key=%s','etsy_webhook:'.$event));self::assertGreaterThan(0,$order);return [$order,$event,$body];}
 private function sortedKeys(array $value):array {$keys=array_keys($value);sort($keys);return $keys;}
}
